// Every language's label for a nav key, so layouts can reserve the widest one.
export const getNavLabels = (key) => SUPPORTED_LANGUAGES.map(({ code }) => translations[code].nav[key])

const I18nContext = createContext(null)

export function I18nProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    const stored = typeof window !== 'undefined' ? localStorage.getItem('language') : null
    return translations[stored] ? stored : 'es'
  })

  useEffect(() => {
    localStorage.setItem('language', language)
    document.documentElement.lang = language
  }, [language])

  const value = useMemo(() => {
    const t = translations[language]
    const translate = (value, params = {}) => Object.entries(params).reduce((text, [key, replacement]) => text.replace(`{${key}}`, replacement), value)
    return { language, setLanguage, t, translate }
  }, [language])

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  return useContext(I18nContext)
}
